                task: '«Грецький вогонь» був винайдений ще за часів античності: ним вистрілювали зі спеціальних сифонів на кораблях, і після влучення в ціль загасити його було неможливо. У складі «грецького вогню» були нафта, сірка, селітра й олія. Обговоріть і визначте правильність тверджень: 1) якщо гасити «грецький вогонь» водою, то нафта й олія спливають на поверхню води й горіння триває; 2) щоб загасити вогонь, необхідно припинити доступ повітря до місця займання, але, крім води й піску, інші засоби в ті часи не були відомі; 3) сучасними засобами пожежогасіння можна було б загасити «грецький вогонь», якщо використовувати пінні вогнегасники.',
